using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long>a(n);
    for(auto &x:a) cin >> x;
    int l = 0, r = n-1;
    while(l<r) {
        int m = l+(r-l)/2;
        if(m%2) m--;
        if(m+1<n && a[m] == a[m+1]) l = m+2;
        else r = m;
    }
    cout << a[l]<<"\n";
}

