int main() {
    int n;
    cin >> n;
    long long first = LLONG_MIN, second = LLONG_MIN, x;
    while(n--) {
        cin >> x;
        if(x>first) {
            second = first;
            first = x;
        }
        else if(x<first && x>second) second = x;
    }
    if(second == LLONG_MIN) cout << "No second largest\n";
    else cout << second<<"\n";
}

