#include <bits/stdc++.h>
using namespace std;
bool valid(const string& s) {
    bool upper = false, digit = false;
    if(s.size()<4 || isdigit((unsigned char)s[0])) return false;
    for(char c:s) {
        if(c == ' ' || c == '/') return false;
        upper| = isupper((unsigned char)c);
        digit| = isdigit((unsigned char)c);
    }
    return upper && digit;
}
char shiftChar(char c, int k) {
    if(isupper((unsigned char)c)) return char('A'+(c-'A'+k)%26);
    if(islower((unsigned char)c)) return char('a'+(c-'a'+k)%26);
    if(isdigit((unsigned char)c)) return char('0'+(c-'0'+k)%10);
    return c;
}
int main() {
    string s;
    int k;
    getline(cin, s);
    cin >> k;
    if(!valid(s)) {
        cout << "Error!\n";
        return 0;
    }
    for(char &c:s) c = shiftChar(c, k);
    cout << s<<"\n";
}

