    char direction;
    cin >> n;
    vector<int> values(n);
    for (int& value : values) cin >> value;
    cin >> k >> direction;
    // L for left, R for right.;
    if (direction == 'L') rotateLeft(values, k);
    else rotateRight(values, k);
    for (int value : values) cout << value << ' ';
    cout << '\n';
    return 0;
}

