    vector<int> values(n);
    for (int& value : values) cin >> value;
    cin >> m;
    vector<int> order(m);
    for (int& value : order) cin >> value;
    for (int value : relativeSort(values, order)) cout << value << ' ';
    cout << '\n';
    return 0;
}

