vector<int> sievePrimes(int limit) {
    vector<bool> isPrime(limit + 1, true);
    if (limit >= 0) isPrime[0] = false;
    if (limit >= 1) isPrime[1] = false;
    for (int number = 2;
    number * number <= limit;
    number++) {
        if (isPrime[number]) {
            for (int multiple = number * number;
            multiple <= limit;
            multiple += number) {
                isPrime[multiple] = false;
            }
        }
    }
    vector<int> primes;
    for (int number = 2;
    number <= limit;
    number++) {
        if (isPrime[number]) primes.push_back(number);
    }
    return primes;
}
