int partitionArray(vector<int>& values, int low, int high) {
    int pivot = values[high];
    int smallerBoundary = low - 1;
    for (int current = low;
    current < high;
    current++) {
        if (values[current] <= pivot) {
            smallerBoundary++;
            swap(values[smallerBoundary], values[current]);
