int repeatedLetterCount(const string& word) {
    unordered_map<char, int> frequency;
    for (char ch : word) frequency[ch]++;
    int repeated = 0;
    for (const auto& entry : frequency) {
        if (entry.second > 1) repeated += entry.second;
    }
    return repeated;
}
int main() {
